<?php require_once '../config/database.php';require_once '../includes/functions.php';require_admin();$pageTitle='Cart Data';$active='cart';$rows=$pdo->query("SELECT c.user_id,u.name user_name,u.email,c.product_id,p.name product_name,p.price,c.quantity,(p.price*c.quantity) total,c.updated_at FROM cart_items c JOIN users u ON u.id=c.user_id JOIN products p ON p.id=c.product_id ORDER BY c.updated_at DESC")->fetchAll();require 'header.php';?><div class="admin-top"><div><span class="eyebrow">Store Data</span><h1>Cart</h1><p>Saved cart items for logged-in customers.</p></div></div><section class="admin-card"><div class="table-scroll"><table class="admin-table"><thead><tr><th>User</th><th>Email</th><th>Product</th><th>Qty</th><th>Item Total</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['user_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['product_name'])?></td><td><?=$r['quantity']?></td><td>₹<?=number_format((float)$r['total'],2)?></td><td><?=e($r['updated_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="empty-row">No saved cart data.</td></tr><?php endif;?></tbody></table></div></section><?php require 'footer.php';
